    def event_data(self, **overrides: Any) -> dict[str, Any]:
        """Build one valid composer submission without sending invitations."""
        return {
            "inbox": self.source.pk,
            "title": "Composer test event",
            "event_timezone": timezone.get_current_timezone_name(),
            "start_date": self.today.isoformat(),
            "end_date": self.today.isoformat(),
            "start_time": "10:00",
            "end_time": "11:00",
            "location": "Meeting room",
            "content": "Agenda notes",
            "data_view_create_id": "calendar-draft",
            **overrides,
        }

    def timed_defaults(self, response: HttpResponse) -> bool:
        """Verify effective Inbox, local hour controls, and the caller survive GET initialization."""
        form = response.context["form"]
        return (
            form.initial["inbox"] == self.source.pk
            and form.initial["start_date"] == self.today
            and form.initial["start_time"] == timezone.localtime(self.start).time()
            and form.initial["end_time"]
            == timezone.localtime(self.start + timedelta(hours=1)).time()
            and response.context["data_view_create_id"] == "calendar-draft"
            and 'id="calendar-event-create-form"' in response.content.decode()
            and "Hello" not in response.content.decode()
        )

    def all_day_defaults(self, response: HttpResponse) -> bool:
        """Show a one-day date range as the same start and end date in the composer."""
        initial = response.context["form"].initial
        return (
            initial["all_day"]
            and initial["start_date"] == initial["end_date"] == self.today
        )

    def timed_saved(self, response: HttpResponse) -> bool:
        """Verify placement, guest deduplication, and the scoped dataview completion event."""
        event = CalendarEvent.objects.get(title="Composer test event")
        trigger = json.loads(response["HX-Trigger"])[
            "bloomerp:data-view-object-created"
        ]
        return (
            event.start == self.start
            and event.end == self.start + timedelta(hours=1)
            and event.start_date is None
            and event.end_date is None
            and not event.all_day
            and event.organizing_inbox_id == self.source.pk
            and list(event.inboxes.all()) == [self.source]
            and set(event.participants.values_list("email", flat=True))
            == {"guest@example.com", "second@example.com"}
            and event.invitation_sent_at is None
            and trigger["data_view_create_id"] == "calendar-draft"
        )

    def all_day_saved(self, response: HttpResponse) -> bool:
        """Confirm exclusive date-only storage and an empty timed representation."""
        event = CalendarEvent.objects.get(title="Composer test event")
        return (
            event.all_day
            and event.start_date == self.today
            and event.end_date == self.today + timedelta(days=1)
            and event.start is None
            and event.end is None
            and event.event_timezone is None
            and event.inboxes.filter(pk=self.source.pk).exists()
        )

    def nothing_saved(self, response: HttpResponse) -> bool:
        """Require form errors and no event for invalid or unauthorized submissions."""
        return (
            bool(response.context["form"].errors)
            and not CalendarEvent.objects.filter(title="Composer test event").exists()
        )

    def invalid_preserves_inputs(self, response: HttpResponse) -> bool:
        """Keep entered title, invalid end time, and modal correlation available for correction."""
        return (
            self.nothing_saved(response)
            and response.context["form"]["title"].value() == "Composer test event"
            and response.context["form"]["end_time"].value() == "09:00"
            and response.context["data_view_create_id"] == "calendar-draft"
        )

    def restrict_optional_fields(self, scenario: RequestScenario) -> None:
        """Remove optional write grants while retaining the actual form/view permission path."""
        from bloomerp.forms.communication.calendar_event import calendar_create_fields

        fields = calendar_create_fields(self.actor) - {"content", "location"}
        self.field_patch = patch(
            "bloomerp.forms.communication.calendar_event.calendar_create_fields",
            return_value=fields,
        )
        self.field_patch.start()

    def restore_optional_fields(self, scenario: RequestScenario) -> None:
        """Restore field grants before the next declarative scenario runs."""
        self.field_patch.stop()

    def restricted_saved(self, response: HttpResponse) -> bool:
        """Ignore submitted values for controls omitted by the add-field policy."""
        event = CalendarEvent.objects.get(title="Composer test event")
        return event.content == "" and event.location == ""

    def composer_controls(self, response: HttpResponse) -> bool:
        """Require shared composer controls and sender-dependent invitations in the second row."""
        html = response.content.decode()
        rows = BeautifulSoup(html, "html.parser").select("#calendar-event-create-form [data-layout-row]")
        return (
            'bloomerp-component="bloomerp-text-editor"' in html
            and 'bloomerp-component="detail-view-value"' in html
            and 'data-layout-item-id="title"' in html
            and 'data-layout-item-id="attendees"' in html
            and 'data-layout-row' in html
            and 'x-show="!allDay"' in html
            and 'bloomerp-component="resizable-div"' in html
            and 'name="event_timezone"' in html
            and "Add an event to your calendar." not in html
            and 'name="organizer_email"' not in html
            and len(rows) > 1
            and rows[1].select_one('[data-layout-item-id="send_invitations"][x-show="Boolean(senderSelected)"]') is not None
            and 'x-model="senderSelected"' in html
            and 'x-bind:disabled="!senderSelected"' in html
        )

    def timezone_saved(self, response: HttpResponse) -> bool:
        """Interpret wall-clock controls in the chosen timezone rather than server timezone."""
        event = CalendarEvent.objects.get(title="Composer test event")
        return (
            event.event_timezone == "Europe/Brussels"
            and event.start.astimezone(ZoneInfo("Europe/Brussels")).hour == 10
        )

    def grant_event_and_user_access(self, scenario: RequestScenario) -> None:
        """Grant event creation and user discovery without any participant model grants."""
        PolicyManager.create_policy(
            CalendarEvent,
            global_permissions=["add"],
            field_permissions={"__all__": ["add"]},
            row_permissions=[RowPolicyRuleContent(permissions=["add"], conditions=[])],
        ).assign_user(self.owner)
        PolicyManager.create_policy(
            get_user_model(),
            global_permissions=["view"],
            field_permissions={"__all__": ["view"]},
            row_permissions=[RowPolicyRuleContent(permissions=["view"], conditions=[])],
        ).assign_user(self.owner)

    def internal_saved(self, response: HttpResponse) -> bool:
        """Place one shared event in the recipient calendar and preserve user identity without emailing."""
        event = CalendarEvent.objects.get(title="Composer test event")
        return (
            set(event.inboxes.values_list("pk", flat=True))
            == {self.source.pk, self.owner_calendar.pk}
            and event.participants.filter(
                user=self.owner, email=self.owner.email
            ).count()
            == 1
            and event.participants.filter(
                user__isnull=True, email="external@example.com"
            ).exists()
            and event.participants.count() == 2
            and event.invitation_sent_at is None
        )

    def mock_delivery(self, scenario: RequestScenario) -> None:
        """Replace only provider delivery while exercising the real scheduling service."""
        self.delivery_patch = patch(
            "bloomerp.communication.calendar.outgoing._send", return_value="message-id"
        )
        self.delivery = self.delivery_patch.start()

    def restore_delivery(self, scenario: RequestScenario) -> None:
        """Restore real provider delivery after this isolated scenario."""
        self.delivery_patch.stop()

    def email_sent(self, response: HttpResponse) -> bool:
        """Verify sender identity, recipients, and sent revision without sending external messages."""
        event = CalendarEvent.objects.get(title="Composer test event")
        return (
            event.organizer_email == self.sender.email_address
            and event.invitation_sent_at is not None
            and self.delivery.call_count == 1
            and self.delivery.call_args.args[4] == ["guest@example.com"]
        )

    def configure_conferencing(self, scenario: RequestScenario) -> None:
        """Enable validated test conferencing without configuring a real external provider."""
        self.conferencing_override = override_settings(
            BLOOMERP_CONFIG=conferencing_config()
        )
        self.conferencing_override.enable()

    def restore_conferencing(self, scenario: RequestScenario) -> None:
        """Restore instance settings before the next request scenario."""
        self.conferencing_override.disable()

    def conference_reserved(self, response: HttpResponse) -> bool:
        """Persist a stable invitation link and a pending session with the creator as host."""
        event = CalendarEvent.objects.get(title="Composer test event")
        session = event.conference_session
        return (
            session is not None
            and session.status == "pending"
            and str(session.share_token) in event.location
            and session.participants.get(role="host").user_id == self.actor.pk
            and not session.livekit_room_sid
        )

    def email_free_saved(self, response: HttpResponse) -> bool:
        """Internal calendar invitations need no email address when sending is disabled."""
        event = CalendarEvent.objects.get(title="Composer test event")
        return (
            event.participants.filter(user=self.outsider, email="").exists()
            and event.inboxes.filter(pk=self.outsider_calendar.pk).exists()
        )

    def mock_failed_delivery(self, scenario: RequestScenario) -> None:
        """Simulate an email transport failure without contacting an external account."""
        self.mock_delivery(scenario)
        self.delivery.side_effect = RuntimeError("Transport unavailable")

    def delivery_failure_saved(self, response: HttpResponse) -> bool:
        """Close the composer with a warning while retaining exactly one unsent event for retry."""
        event = CalendarEvent.objects.get(title="Composer test event")
        detail = json.loads(response["HX-Trigger"])["bloomerp:data-view-object-created"]
        return (
            event.invitation_sent_at is None
            and detail["messages"][0]["type"] == "warning"
            and "Edit the event to retry sending." in detail["messages"][0]["text"]
        )

    def test_inbox_token_survives_dataview_create_and_post(self) -> None:
        """An Inbox owner without event policies can render, compose, and save only in that Inbox."""
        import html
        import re
        from urllib.parse import parse_qs, urlsplit

        from django.urls import reverse

        from bloomerp.permissions.manager import UserPolicyManager

        self.assertFalse(UserPolicyManager(self.owner).has_global_permission(CalendarEvent, "add"))
        self.client.force_login(self.owner)
        page = self.client.get(reverse("inbox_calendar", kwargs={"inbox_id": self.source.pk}))
        self.assertEqual(page.status_code, 200)
        embedded = re.search(r'hx-get="([^"]*components/dataview/[^"]*)"', page.content.decode())
        self.assertIsNotNone(embedded)
        dataview = self.client.get(html.unescape(embedded.group(1)))
        self.assertEqual(dataview.status_code, 200)
        self.assertContains(dataview, self.timed.title)
        self.assertNotContains(dataview, self.unplaced.title)
        create_url = dataview.context["create_component_url"]
        self.assertIsNotNone(create_url)
        composer = self.client.get(create_url + "&data_view_create_id=calendar-draft")
        self.assertContains(composer, 'name="_permission_token"')
        token = parse_qs(urlsplit(create_url).query)["_permission_token"][0]
        unfiltered = self.client.get(urlsplit(html.unescape(embedded.group(1))).path, {"_permission_token": token})
        self.assertNotContains(unfiltered, self.unplaced.title)
        self.assertContains(unfiltered, self.timed.title)
        action = composer.context["form_url"]
        response = self.client.post(action, self.event_data(_permission_token=token))
        self.assertEqual(response.status_code, 204)
        event = CalendarEvent.objects.get(title="Composer test event")
        self.assertEqual(event.organizing_inbox_id, self.source.pk)
        # A different owned Inbox passes normal choice validation but not the signed add predicate.
        denied = self.client.post(action, self.event_data(
            _permission_token=token, inbox=self.owner_calendar.pk, title="Outside signed inbox",
        ))
        self.assertEqual(denied.status_code, 200)
        self.assertContains(denied, "You cannot create events in this calendar.")
        self.assertFalse(CalendarEvent.objects.filter(title="Outside signed inbox").exists())
